package exercise

import (
	"reflect"
	"sync"
	"testing"
	"time"
)

func TestCheckWebsites(t *testing.T) {
	urls := []string{
		"http://google.com",
		"http://blog.gypsydave5.com",
		"waat://furhurterwe.geds",
	}

	checker := func(url string) bool {
		return url != "waat://furhurterwe.geds"
	}

	want := map[string]bool{
		"http://google.com":          true,
		"http://blog.gypsydave5.com": true,
		"waat://furhurterwe.geds":    false,
	}

	got := CheckWebsites(checker, urls)

	if !reflect.DeepEqual(want, got) {
		t.Errorf("wanted %v, got %v", want, got)
	}
}

func TestCheckWebsitesWithNoURLs(t *testing.T) {
	got := CheckWebsites(func(string) bool { return true }, nil)

	if len(got) != 0 {
		t.Errorf("wanted an empty result, got %v", got)
	}
}

func TestCheckWebsitesRunsChecksConcurrently(t *testing.T) {
	urls := []string{"a", "b", "c", "d", "e"}

	var wg sync.WaitGroup
	wg.Add(len(urls))

	allStarted := make(chan struct{})
	go func() {
		wg.Wait()
		close(allStarted)
	}()

	timedOut := make(chan struct{})
	time.AfterFunc(time.Second, func() { close(timedOut) })

	// Every check blocks until all of them have started. That can only happen
	// if the checks run at the same time; a sequential implementation stalls
	// until the timeout and reports false.
	checker := func(url string) bool {
		wg.Done()
		select {
		case <-allStarted:
			return true
		case <-timedOut:
			return false
		}
	}

	got := CheckWebsites(checker, urls)

	for _, url := range urls {
		if !got[url] {
			t.Fatalf("the checks did not all run at the same time, got %v", got)
		}
	}
}

